let KB_DATA = BUILT_IN_KB_DATA;

function okbApplyLoadedKnowledgeBase(data) {
  if (data && data.categories) {
    KB_DATA = data;
    console.log('Offline KB loaded from UI_Knowledge_base.json');
  }
}

function okbLoadExternalKnowledgeBase() {
  if (!window.fetch) return;
  fetch('UI_Knowledge_base.json')
    .then(resp => {
      if (!resp.ok) throw new Error('KB fetch failed: ' + resp.status);
      return resp.json();
    })
    .then(data => okbApplyLoadedKnowledgeBase(data))
    .catch(err => {
      console.warn('Could not load external KB:', err);
    });
}

function okbInitExternalKnowledgeBase() {
  if (document.readyState === 'complete' || document.readyState === 'interactive') {
    okbLoadExternalKnowledgeBase();
  } else {
    window.addEventListener('DOMContentLoaded', okbLoadExternalKnowledgeBase);
  }
}

if (typeof window !== 'undefined') {
  okbInitExternalKnowledgeBase();
}

/* ═══════════════════════════════════════════════════════════
   offlineKnowledgeBase.js
   Pure-JavaScript, no-AI, no-API matching engine over the local
   mental-wellness knowledge base (KB_DATA above). Used whenever
   the app is running in Offline Mode (see FEATURE 7 / 8).
   ═══════════════════════════════════════════════════ */

/**
 * Lower-cases and strips punctuation from a string so keyword /
 * phrase comparisons aren't thrown off by case or punctuation.
 * @param {string} s
 * @returns {string}
 */
function okbNormalize(s) {
  return (s || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Common function words excluded from similarity scoring so two
// phrases don't look alike just because they both say "I feel...".
const OKB_STOPWORDS = new Set(['i','a','the','am','is','are','to','my','me','and','so','of','in','on','it','feel','feeling','felt','this','that','im']);

/**
 * Very small string-similarity helper (content-word overlap
 * ratio, stopwords excluded). Good enough for "basic similarity"
 * matching against short phrases without needing any external
 * library.
 * @param {string} a
 * @param {string} b
 * @returns {number} 0..1 overlap score
 */
function okbSimilarity(a, b) {
  const wa = new Set(okbNormalize(a).split(' ').filter(w => w && !OKB_STOPWORDS.has(w)));
  const wb = new Set(okbNormalize(b).split(' ').filter(w => w && !OKB_STOPWORDS.has(w)));
  if (wa.size === 0 || wb.size === 0) return 0;
  let overlap = 0;
  wa.forEach(w => { if (wb.has(w)) overlap++; });
  return overlap / Math.min(wa.size, wb.size);
}

/**
 * Stem-ish keyword check: catches close forms like "anxious" vs
 * a stored keyword "anxiety" by comparing word roots, in addition
 * to plain substring containment.
 * @param {string} normText
 * @param {string} keyword
 * @returns {boolean}
 */
function okbKeywordHit(normText, keyword) {
  const normKw = okbNormalize(keyword);
  if (normText.includes(normKw)) return true;
  const kwRoot = normKw.split(' ')[0].slice(0, 5);
  if (kwRoot.length < 4) return false;
  return normText.split(' ').some(w => w.length >= 4 && w.slice(0, 5) === kwRoot);
}

/**
 * Scores a single intent against the user's message using
 * keyword containment, phrase containment, and word-overlap
 * similarity. Higher is a better match.
 * @param {string} userText
 * @param {object} intent
 * @returns {number}
 */
function okbScoreIntent(userText, intent) {
  const norm = okbNormalize(userText);
  let score = 0;

  (intent.keywords || []).forEach(kw => {
    if (okbKeywordHit(norm, kw)) score += 2;
  });

  (intent.phrases || []).forEach(ph => {
    const normPh = okbNormalize(ph);
    if (norm.includes(normPh)) {
      score += 3;
    } else {
      const sim = okbSimilarity(userText, ph);
      if (sim >= 0.6) score += sim * 2;
    }
  });

  return score;
}

/**
 * Searches every category/intent in KB_DATA for the best match
 * to the given user text.
 * @param {string} userText
 * @returns {{category:string, intent:object, score:number}|null}
 */
function okbFindBestMatch(userText) {
  if (!userText || !okbNormalize(userText)) return null;
  let best = null;
  const categories = (KB_DATA && KB_DATA.categories) || {};
  Object.keys(categories).forEach(catName => {
    const cat = categories[catName];
    (cat.intents || []).forEach(intent => {
      const score = okbScoreIntent(userText, intent);
      if (score > 0 && (!best || score > best.score)) {
        best = { category: catName, intent, score };
      }
    });
  });
  return best;
}

/**
 * Public entry point: given raw user text, returns a structured
 * offline reply. Always returns something usable — falls back to
 * a gentle "no exact match" message rather than ever erroring.
 * @param {string} userText
 * @returns {{matched:boolean, category:?string, response:string, affirmations:string[], coping_steps:string[], follow_up_questions:string[]}}
 */
function getOfflineResponse(userText) {
  const match = okbFindBestMatch(userText);
  if (!match || match.score < 2) {
    return {
      matched: false,
      category: null,
      response: "I couldn't find an exact match, but here's something that may help: it's okay to not have all the answers right now. Naming how you feel is already a good first step. Would you like to tell me a little more?",
      affirmations: ["I am doing the best I can with what I have right now."],
      coping_steps: ["Take a slow breath in, and let it out gently.", "Try writing the feeling down in your journal."],
      follow_up_questions: ["Can you tell me a bit more about what's going on?"]
    };
  }
  const intent = match.intent;
  return {
    matched: true,
    category: match.category,
    response: intent.response || '',
    affirmations: intent.affirmations || [],
    coping_steps: intent.coping_steps || [],
    follow_up_questions: intent.chain_questions || []
  };
}

// Expose as a small namespaced API so other modules (chat wiring)
// can call it without polluting globals further.
window.OfflineKB = {
  getOfflineResponse
};